package config

type EngineCap struct {
	// Type of engine (one of "detection", "classification", "guidance", "position"
	// "generic", "filter")
	Type string `toml:"type"`
	// Input types supported by this engine
	Inputs []string `toml:"inputs"`
	// Result type generated by this engine
	Result string `toml:"result"`
}

// MatchesInputType checks whether an engine accepts the given input type.
func (e *EngineCap) MatchesInputType(inputType string) bool {
	for _, i := range e.Inputs {
		if i == inputType {
			return true
		}
	}
	return false
}

// MatchesResultType checks whether an engine generates the given result type.
func (e *EngineCap) MatchesResultType(resultType string) bool {
	return e.Result == resultType
}
